-- Foundation draft. Not yet registered as a hosted migration or applied in production.
PRAGMA foreign_keys = ON;
CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE memberships (workspace_id TEXT NOT NULL REFERENCES workspaces(id), user_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','operator','viewer')), status TEXT NOT NULL CHECK(status IN ('active','disabled','invited')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE creator_accounts (workspace_id TEXT NOT NULL REFERENCES workspaces(id), id TEXT NOT NULL, display_name TEXT NOT NULL, provider TEXT, external_id TEXT, connection_status TEXT NOT NULL DEFAULT 'disconnected' CHECK(connection_status IN ('disconnected','pending','connected','error')), PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,provider,external_id));
CREATE TABLE account_grants (workspace_id TEXT NOT NULL, user_id TEXT NOT NULL, creator_id TEXT NOT NULL, permission TEXT NOT NULL CHECK(permission IN ('read','notes','drafts','send','settings')), PRIMARY KEY(workspace_id,user_id,creator_id,permission), FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id), FOREIGN KEY(workspace_id,creator_id) REFERENCES creator_accounts(workspace_id,id));
CREATE TABLE fans (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, id TEXT NOT NULL, display_name TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,creator_id) REFERENCES creator_accounts(workspace_id,id));
CREATE TABLE fan_notes (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, fan_id TEXT NOT NULL, body TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,creator_id,fan_id), FOREIGN KEY(workspace_id,creator_id,fan_id) REFERENCES fans(workspace_id,creator_id,id));
CREATE TABLE messages (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, fan_id TEXT NOT NULL, id TEXT NOT NULL, direction TEXT NOT NULL CHECK(direction IN ('inbound','outbound')), body TEXT NOT NULL, occurred_at TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,creator_id,fan_id) REFERENCES fans(workspace_id,creator_id,id));
CREATE TABLE drafts (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, fan_id TEXT NOT NULL, user_id TEXT NOT NULL, body TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,fan_id,user_id), FOREIGN KEY(workspace_id,creator_id,fan_id) REFERENCES fans(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,user_id) REFERENCES memberships(workspace_id,user_id));
CREATE TABLE transactions (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, id TEXT NOT NULL, fan_id TEXT NOT NULL, gross_cents INTEGER NOT NULL, fee_cents INTEGER NOT NULL, currency TEXT NOT NULL, category TEXT NOT NULL, occurred_at TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,creator_id,fan_id) REFERENCES fans(workspace_id,creator_id,id));
CREATE TABLE vault_folders (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,creator_id) REFERENCES creator_accounts(workspace_id,id));
CREATE TABLE vault_media (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, media_type TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,creator_id) REFERENCES creator_accounts(workspace_id,id));
CREATE TABLE vault_folder_media (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, folder_id TEXT NOT NULL, media_id TEXT NOT NULL, PRIMARY KEY(workspace_id,creator_id,folder_id,media_id), FOREIGN KEY(workspace_id,creator_id,folder_id) REFERENCES vault_folders(workspace_id,creator_id,id), FOREIGN KEY(workspace_id,creator_id,media_id) REFERENCES vault_media(workspace_id,creator_id,id));
CREATE TABLE bruff_settings (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, mode TEXT NOT NULL DEFAULT 'off' CHECK(mode IN ('off','selected','all')), review_required INTEGER NOT NULL DEFAULT 1 CHECK(review_required IN (0,1)), config_json TEXT NOT NULL DEFAULT '{}', version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,creator_id), FOREIGN KEY(workspace_id,creator_id) REFERENCES creator_accounts(workspace_id,id));
CREATE TABLE bruff_chat_overrides (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, fan_id TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('manual','enabled')), PRIMARY KEY(workspace_id,creator_id,fan_id), FOREIGN KEY(workspace_id,creator_id,fan_id) REFERENCES fans(workspace_id,creator_id,id));
CREATE TABLE sync_cursors (workspace_id TEXT NOT NULL, creator_id TEXT NOT NULL, resource TEXT NOT NULL, cursor TEXT, last_success_at TEXT, PRIMARY KEY(workspace_id,creator_id,resource), FOREIGN KEY(workspace_id,creator_id) REFERENCES creator_accounts(workspace_id,id));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), actor_id TEXT NOT NULL, action TEXT NOT NULL, resource_id TEXT, occurred_at TEXT NOT NULL);
